css:
/* Shorts shelves on Home, Subscriptions and Search */
ytd-rich-section-renderer:has(ytd-rich-shelf-renderer[is-shorts]),
ytd-reel-shelf-renderer,
ytd-rich-item-renderer:has(a[href^="/shorts/"]),
ytd-video-renderer:has(a[href^="/shorts/"]),
ytd-grid-video-renderer:has(a[href^="/shorts/"]) {
  display: none !important;
}

/* Shorts entry in the sidebar, mini sidebar and filter chips */
ytd-guide-entry-renderer:has(a[title="Shorts"]),
ytd-mini-guide-entry-renderer[aria-label="Shorts"],
yt-chip-cloud-chip-renderer:has([title="Shorts"]),
yt-tab-shape[tab-title="Shorts"] {
  display: none !important;
}

js:
// /shorts/<id> -> /watch?v=<id>, on load and on in-app navigation
const unshort = () => {
  const m = location.pathname.match(/^\/shorts\/([\w-]{6,})/);
  if (m) location.replace("/watch?v=" + m[1]);
};
unshort();
morse.on(document, "yt-navigate-finish", unshort);
